ProjectALife.DialogueShards["scenes_any_22"] = {
{"s4_jail_three_hots_011","any",3,"reg=law|day=6,120|mood=funny|world=inside",{1,"Three hots and a cot, that's what the boys in here used to call it",2,"I miss when we could complain about that",3,"Never thought a hot meal and somewhere to lie down would sound so good"}},
{"s4_jail_nurse_insulin_012","any",2,"reg=law|day=2,30|mood=warm|world=fence",{1,"Nurse Abernathy stayed, jail nurse, fifty-nine years old, everybody else went over the fence",2,"Why'd she stay?",1,"Said her insulin patients weren't gonna give themselves their shots, now were they"}},
{"s4_jail_lock_myself_in_013","any",2,"reg=law|role=law_corrections,law_deputy,law_sergeant|day=5,120|mood=grim|world=building",{1,"Eleven years I spent counting the hours till I got out of this building",2,"And now?",1,"Now I lock myself in it every night and say thank you"}},
{"s4_jail_mother_at_glass_014","any",2,"reg=law|day=2,20|mood=sad",{1,"Woman at the front glass asking after her boy - Kevin Ashby - Possession",2,"Was he one we let walk?",1,"Walked out Saturday with his property bag",2,"Did you tell her?",1,"She asked which way he went, I said north - she looked like she needed a direction"}},
{"s4_jail_county_orange_015","any",2,"reg=law|day=5,120|mood=grim",{1,"Saw three of 'em in county orange out on 31W today",2,"Ours?",1,"Didn't get close enough to read the stencil on the back - didn't want to"}},
{"s4_jail_monday_docket_016","any",2,"reg=law|day=3,12|mood=funny",{1,"Monday's docket had forty-one cases on it",2,"Continuance?",1,"Indefinite, I'd say the motion's granted"}},
{"s4_jail_eddyville_017","any",3,"reg=law|day=3,40|mood=funny",{1,"Old man in cell four did twenty years at Eddyville - he asked me was it safe to go out",2,"What'd you tell him?",1,"Told him no, he said, well then, I'll stay, like I'd offered him a ride someplace",3,"Smartest man in the building"}},
{"s4_jail_broom_handle_018","any",2,"reg=law|role=law_corrections|day=1,6|mood=fear",{1,"Walked the tier with a flashlight and a broom handle - that's what the Commonwealth issued me",2,"A broom handle?",1,"No guns past the sally port. They stay in the lockbox, ours too",2,"Right. Wouldn't want to break that one"}},
{"s4_jail_bondsman_receipt_019","any",2,"reg=law|day=1,5|mood=funny",{1,"Bail bondsman showed up Saturday to post bond on a client",2,"In the middle of all this?",1,"Said a deal's a deal - paid cash, I wrote him a receipt",2,"You wrote him a receipt",1,"It's procedure"}},
{"s4_jail_hayes_still_020","any",2,"reg=law|day=6,60|mood=grim",{1,"Darnell Hayes is still in B pod",2,"Still? Nobody's fed B pod in a week",1,"I didn't say he was still eating"}},
{"s4_jail_gray_shirt_021","any",2,"reg=law|day=8,120|mood=funny",{1,"Quit wearing the jail uniform, gray shirt, dark pants - from ten feet it looks like a jumpsuit",2,"Folks shooting at you?",1,"A deputy did, took me for an escapee - hand to God",2,"Which deputy?",1,"Not saying, but he's sitting real close to you"}},
{"s4_jail_work_crew_022","any",3,"reg=law|day=1,5|mood=sad|world=trees",{1,"Friday morning I had a work crew picking trash on the shoulder of 31W - six men in vests",2,"They all come back?",1,"Five, the sixth took off into the trees at lunch",3,"Smartest one of the six",1,"That's all I think about"}},
{"s4_jail_mutter_crayon_023","any",1,"reg=law|day=3,90|mood=sad|world=window",{1,"Visitation room still has the little plastic kid chairs",1,"Crayon picture taped to window three, purple house, a dog, says DADDY across the top"}},
{"s4_jail_through_bars_024","any",3,"reg=law|day=2,20|mood=angry",{1,"We should've put the sick ones down through the bars the first night",2,"They were inmates, in our custody",1,"They were in custody, now they're loose in the pods and we're the ones locked in control",3,"Keep it down, control room ain't soundproof"}},
{"s4_jail_camera_four_025","any",2,"reg=law|day=2,20|hour=22,5|mood=fear|world=building",{1,"Camera four's showing movement in the kitchen",2,"Camera four's been broke since May",1,"Then you tell me what I'm looking at"}},
{"s4_jail_generator_days_026","any",2,"reg=law|day=3,60|mood=calm|world=generator",{1,"Generator's got fuel for nine days if we run the walk-in cooler and the control room, nothing else",2,"Cameras?",1,"Cameras go, we got eyes"}},
{"s4_jail_marcus_polite_027","any",2,"reg=law|day=2,40|mood=warm|world=door",{1,"Kid named Marcus pulled me up off the floor in C pod - door was wide open, he could've run",2,"Did he?",1,"He helped me crank it shut first, then he asked could he go now - real polite - Sir, can I go now"}},
{"s4_jail_booking_binder_028","any",2,"reg=law|day=10,120|mood=grim|world=road",{1,"I kept the booking photo binder, everybody we released",2,"Why haul that around?",1,"So when one of them's standing in the road with a rifle, I know if I'm talking to a check kiter or a Hayes"}},
{"s4_jail_commissary_audit_029","any",2,"reg=law|day=4,60|mood=funny",{1,"Commissary had three cases of peanut butter crackers and a case of noodle cups",2,"Had?",1,"I signed for every box, I want that on the record, somebody's gonna audit me"}},
{"s4_jail_mutter_key_ring_030","any",1,"reg=law|day=2,90|mood=calm|world=door",{1,"Forty-two keys on this ring, I know every one of 'em by feel in the dark",1,"Only need the front door key anymore",1,"Still carry all forty-two"}},
{"s4_jail_d_pod_rattle_031","any",2,"reg=law|day=3,40|hour=21,4|mood=fear",{1,"You hear that? Bars rattling in D pod",2,"D pod's empty, we cleared D pod on Sunday",1,"Then who's rattling?",2,"Get a flashlight, not the big one, the one that has batteries"}},
{"s4_jail_prison_bus_032","any",2,"reg=law|day=1,6|mood=fear|world=vehicle,door",{1,"State transport bus broke down outside Rosewood, fifty-two men aboard and two guards",2,"Where's it now?",1,"Still sitting on the shoulder - door's open, I drove past slow and I did not stop"}},
{"s4_jail_free_men_033","any",3,"reg=law|day=8,120|mood=angry",{1,"Heard the ones that busted out of the prison are calling themselves free men now",2,"Free men carrying our shotguns",3,"They can call themselves the Baptist choir, I still got their numbers memorized"}},
{"s4_jail_walkman_batteries_034","any",2,"reg=law|day=3,40|mood=sad",{1,"Nineteen-year-old in cell two for missing court on a speeding ticket - a speeding ticket",2,"You let him go?",1,"Sunday, gave him back his belt and his shoelaces and his Walkman - he asked me did I have batteries"}},
{"s4_jail_asked_to_stay_035","any",2,"reg=law|day=2,30|mood=funny|world=door",{1,"Four inmates asked to stay locked up when we opened the doors",2,"Four sensible men",1,"Three sensible, the fourth just owed money to somebody in Irvington"}},
{"s4_jail_sheriffs_decision_036","any",3,"reg=law|tmp=veteran,seasoned|day=2,20|mood=grim",{1,"Sheriff's decision - Nonviolent go home, violent stay, with water and a week of food",2,"And after the week?",1,"After the week it's the sheriff's decision again",3,"The sheriff's dead",1,"Then it's mine"}},
{"s4_jail_blue_mattress_037","any",3,"reg=law|day=4,90|hour=4,11|mood=funny",{1,"Slept on an inmate mattress last night - blue vinyl, two inches thick",2,"How was it?",1,"I understand the inmates a whole lot better this morning",3,"You were always mean before your coffee - don't blame the mattress"}},
{"s4_jail_rolled_sleeves_038","any",2,"reg=law|day=0,4|mood=fear|world=vehicle",{1,"Leg irons, belly chain, cuffs, man was trussed up like a Christmas ham and still got his teeth into Sergeant Lyle",2,"Through the uniform?",1,"Forearm - Lyle had his sleeves rolled, it was ninety-five degrees in that van"}},
{"s4_jail_mutter_mail_bin_039","any",1,"reg=law|day=4,90|mood=sad",{1,"Outgoing mail bin's still full, inmate letters, stamped and sealed",1,"Put 'em in my duffel, post office don't open back up, I'll walk 'em around myself"}},
{"s4_jail_block_walls_040","any",2,"reg=law|tmp=veteran|day=10,120|mood=calm|world=fence",{1,"Eighteen inches of block, razor wire on the yard - one way in",2,"Built to keep people in",1,"Concrete don't know which side of it you're standing on"}},
{"s4_jail_otis_menu_041","any",3,"reg=law|day=6,90|mood=funny",{1,"Otis says if we're keeping him around, he wants his kitchen back",2,"He's not in custody anymore",1,"I told him that, he said then he's a volunteer, and volunteers pick the menu",3,"What's on the menu?",1,"Beans, he's real proud of it"}},
{"s4_jail_count_again_042","any",2,"reg=law|role=law_corrections,law_deputy|day=2,60|mood=fear",{1,"Count again",2,"I counted twice - nine",1,"We had ten in the dayroom at noon",2,"Counting again"}},
{"s4_jail_intake_wall_043","any",2,"reg=law|day=3,40|mood=sad|world=building",{1,"Somebody scratched words into the intake cell wall - fresh - tell my mom it wasn't the drugs",2,"Who was in intake?",1,"Three different men this week, none of 'em around to ask"}},
{"s4_jail_he_wasnt_sick_044","any",2,"reg=law|day=3,30|mood=angry",{1,"You locked a man in a cage and walked off - say it like it is",2,"I locked a sick man in a cage so he couldn't bite the well ones",1,"He wasn't sick when you turned the key",2,"He was by the time I got it back out of the lock"}},
{"s4_jail_mutter_tap_bars_045","any",1,"reg=law|day=2,40|mood=grim",{1,"Tap the bars on every cell going by - habit, tap, tap, tap",1,"Nine grabbed my baton",1,"Not tapping nine anymore"}},
{"s4_jail_relieve_window_046","any",2,"reg=law|role=law_corrections,law_deputy,law_officer|day=6,120|mood=funny",{1,"Shift change, I'm relieving you",2,"Relieving me to go where, exactly?",1,"Other end of the hall, it's got a window",2,"Well, why didn't you say so - hot dog"}},
{"s4_jail_juvenile_hold_047","any",2,"reg=law|day=2,20|mood=sad",{1,"Juvenile hold had one kid - fourteen, lifted a cassette from the Rosewood pharmacy",2,"Where is he now?",1,"Asleep in the break room, won't leave till somebody comes - asks me every hour did his mom call"}},
{"s4_jail_reds_losing_048","any",2,"reg=law|day=4,90|mood=warm",{1,"C pod used to beg me for the Reds game on the radio - station out of Cincinnati",2,"You let 'em have it?",1,"Only when the Reds were losing, gave them something else to be mad at besides me"}},
{"s4_jail_one_night_looter_049","any",3,"reg=law|day=14,150|mood=grim",{1,"Caught one of the looters from the hardware store - what do we do with him?",2,"Put him in a cell",3,"And feed him what? We're down to commissary crackers ourselves",1,"One night in a cell, then we let him walk and tell everybody the jail's still open"}},
{"s4_jail_fort_desk_050","any",2,"reg=law|tmp=veteran|day=20,200|mood=grim",{1,"We're not a jail anymore, we're a fort with a booking desk",2,"Somebody still sits at that desk every morning",1,"That's the part I can't let go of"}},
{"s4_jail_brights_three_051","any",2,"reg=law|day=5,90|hour=22,4|mood=fear|world=vehicle",{1,"Car pulled up to the sally port gate at midnight - flashed its brights three times",2,"One of ours?",1,"Ours used to flash three, nobody got out - by dawn it was gone"}},
{"s4_jail_razor_wire_hands_052","any",3,"reg=law|day=4,60|mood=grim|world=fence",{1,"One got hung up in razor wire in the east yard once",2,"Was it still moving?",1,"Moving and making noise. We worried about what else might hear",3,"I remember wishing we'd worked out how to handle that before it happened"}},
{"s4_jail_mutter_booking_number_053","any",1,"reg=law|role=law_corrections|day=10,200|mood=angry",{1,"Nine three oh seven one four, that's the number I gave him",1,"Now he's out there with a deer rifle robbing folks on 31W",1,"I'll see that number again, I'll see it"}},
{"s4_partner_coffee_maker_001","any",2,"reg=law|day=1,10|mood=fear|world=vehicle",{1,"Danny kept his left hand in his jacket pocket the whole shift - in July",2,"Said he burned it on the coffee maker",1,"We don't have a coffee maker in that car",2,"I know we don't"}},
{"s4_partner_diner_handshake_002","any",2,"reg=law,swat|tmp=seasoned,veteran|day=2,30|mood=grim|world=road",{1,"He made me shake on it in the diner parking lot, back in April - like a joke, if I ever come back from the dead on you, you do it",2,"And when it came to it?",1,"I kept my word, took his badge off first, didn't want it getting dirty"}},
{"s4_partner_mutter_thermos_003","any",1,"reg=law|day=3,60|mood=sad",{1,"His thermos is still rolling around under the passenger seat",1,"Every time I brake it knocks my heel, I leave it right there"}},
{"s4_partner_locker_lunch_004","any",3,"reg=law|day=4,30|mood=sad",{1,"Somebody's got to clean out Hatcher's locker",2,"Leave it be",3,"His lunch is in there, six days now, the whole hall smells like it",2,"Then take the lunch out - leave the rest of it"}},
{"s4_partner_unit_fourteen_005","any",2,"reg=law|day=3,60|mood=sad",{1,"Nobody's used Unit 14 on the air since Carl",2,"It's just a number",1,"Then you take it",2,"I'll stay 22"}},
{"s4_partner_salt_coffee_006","any",2,"reg=law|day=6,90|mood=sad",{1,"Mitch made the worst coffee in the Commonwealth - put salt in it - salt! Said his daddy did",2,"I remember - heh, tasted like the bottom of the Ohio",1,"Every morning he'd hold the cup out at me, just try it, just try it one more time, he'd go",2,"Yeah"}},
{"s4_partner_fingernail_007","any",2,"reg=law|tmp=seasoned|day=2,20|mood=funny",{1,"Old boy I cuffed on the Muldraugh call got a fingernail in my wrist, first suspect in years who really meant it, hahaha!",2,"Let me see the wrist",1,"It's a scratch, I'm gonna go get some air"}},
{"s4_partner_sherry_knock_008","any",3,"reg=law|day=2,15|mood=sad",{1,"Somebody has to go tell Sherry about Wade",2,"Sherry's house has been dark since Saturday",3,"Then there's nobody to tell",1,"I'm still gonna go knock"}},
{"s4_partner_ditch_radio_009","any",2,"reg=law|day=0,6|mood=fear",{1,"I called officer down on every channel we have - nobody came",2,"There was nobody left to come, that's not on you",1,"Sat with him in the ditch forty minutes, held his radio up by his ear so he could hear somebody trying"}},
{"s4_partner_earl_pike_010","any",2,"reg=law|day=5,90|mood=sad",{1,"His name was Earl Pike - badge two-eleven",2,"Earl Pike",1,"Somebody besides me needed to say it - that's all",2,"Earl Pike, two-eleven, I've got it now"}},
{"s4_partner_collins_plaque_011","any",3,"reg=law|day=1,12|mood=grim",{1,"The Collins kid was on the job nineteen days",2,"Eighteen, his first shift was the twenty-first of June",3,"Does it matter?",2,"It matters to his mama, it'll go on the plaque",1,"There's no plaque",2,"There's gonna be one"}},
{"s4_partner_mutter_seven_012","any",1,"reg=law|day=8,120|mood=grim",{1,"Seven, seven of ours since the ninth",1,"Not saying it for anybody, saying it so it's out loud somewhere besides in my head"}},
{"s4_partner_bass_boat_013","any",2,"reg=law|day=5,60|mood=sad",{1,"Tolliver was two payments from owning that bass boat free and clear",2,"It's still on the trailer behind his place",1,"Checked the tarp yesterday, wind had it loose - I tied it back down"}},
{"s4_partner_debs_car_014","any",2,"reg=law|day=3,60|mood=warm",{1,"You'd have liked Deb, she'd have made you peel off those wet socks before you sat in her car",2,"Her car?",1,"Unit 9 was her car, I just got to drive it some"}},
{"s4_partner_bag_of_ice_015","any",2,"reg=law|day=2,30|mood=sad",{1,"Last thing Hollis ever put out on the air was, grab a bag of ice on your way back in",2,"Did you?",1,"It's still in my trunk - water now"}},
{"s4_partner_fifty_five_016","any",2,"reg=law|day=3,40|mood=sad",{1,"That last morning I told Garrett he drove like somebody's granny - hand to God, he did",2,"Fifty-five everywhere, even Code 3",1,"Just wasn't what I'd have picked for the last thing I said to him"}},
{"s4_partner_senior_officer_017","any",3,"reg=law,swat|tmp=veteran|day=3,30|mood=grim",{1,"One of us gets bit, it's his call, he can walk off, or he can ask",2,"And if he won't choose?",1,"Then the senior officer chooses for him",3,"Who's senior?",1,"Look around, son"}},
{"s4_partner_mutter_two_coffees_018","any",1,"reg=law|day=4,90|hour=5,10|mood=sad",{1,"Poured two cups again this morning",1,"Stood at the counter a good minute holding his before I drank it"}},
{"s4_partner_left_glove_019","any",2,"reg=law|day=3,30|mood=sad|world=door",{1,"Found one of Rick's gloves in the door pocket - the left",2,"Where's the right one?",1,"He had it on"}},
{"s4_partner_crossed_notes_020","any",2,"reg=law|day=2,20|mood=sad|world=road",{1,"Luanne drove to the West Point station to find me - I drove to Muldraugh looking for her",2,"You passed each other on the road?",1,"Found her note taped to my desk, waited an hour, going to yours"}},
{"s4_partner_chihuahua_021","any",3,"reg=law|day=3,40|mood=funny",{1,"Pruitt was the only deputy in this county ever bit by a suspect twice - before all this",2,"Once was nineteen eighty-eight, and it was a woman in a bathrobe",3,"And the other time?",2,"A Chihuahua... a witness, I'll have you know, not a suspect",1,"Hostile witness"}},
{"s4_partner_sally_port_022","any",2,"reg=law|day=1,30|mood=sad|world=door",{1,"Tammy put her back against the sally port door, told me go get the shotgun",2,"You get it?",1,"I got the shotgun"}},
{"s4_partner_lonnies_chair_023","any",3,"reg=law|day=5,90|mood=warm",{1,"How come nobody sits in that chair?",2,"That's Lonnie's",1,"It's a folding chair",3,"It's Lonnie's folding chair - sit on the cooler"}},
{"s4_partner_fifteen_wide_024","any",2,"reg=law|day=4,60|mood=sad",{1,"Big Tom's duty boots are still under the bench - fifteen wide",2,"Somebody could use those",1,"Name me somebody",2,"Yeah, alright"}},
{"s4_partner_never_drew_025","any",2,"reg=law|day=1,14|mood=grim",{1,"Shepherd was the best I ever saw at talking a man down - nineteen years and never drew his weapon",2,"That's what did it?",1,"He kept saying sir, sir, show me your hands, and it just kept on walking"}},
{"s4_partner_retire_bet_026","any",2,"reg=law|tmp=seasoned,veteran|day=6,60|mood=funny",{1,"Me and Ward had twenty bucks on who'd retire first",2,"Who won?",1,"Well, he ain't drawing a pension, I figure I'm up twenty",2,"Give it to his wife",1,"I would"}},
{"s4_partner_mutter_unit_six_027","any",1,"reg=law|day=6,90|hour=22,4|mood=sad|world=water",{1,"Unit 6 to Unit 11 - quiet night, river's up a little",1,"I know you're not out there, telling you anyway. 10-4"}},
{"s4_partner_blood_draw_028","any",3,"reg=law|day=1,6|mood=fear",{1,"Doctor at the ER drew blood off Kenny, said she'd call with the results",2,"Phones are down",3,"She said she'd call",1,"That's what I'm saying, she said it like she meant it"}},
{"s4_partner_church_lot_029","any",2,"reg=law|day=2,20|mood=grim",{1,"Jimmy turned in the back of my car on Wednesday",2,"What'd you do?",1,"What you do, pulled into the Methodist church lot so it'd at least be somewhere decent"}},
{"s4_partner_porch_blame_030","any",3,"reg=law|day=2,15|mood=angry|world=building",{1,"You left him on that porch",2,"He had it on his arm already, he looked right at me and said go",3,"Both of you hush, he's gone either way",1,"It matters how",3,"Not to him it don't"}},
{"s4_partner_dunk_tank_031","any",2,"reg=law|day=5,90|mood=sad|world=rain",{1,"Only picture I got of me and Bud is at the county fair dunk tank - I'm soaked and he's laughing so hard he's a blur",2,"That's a good picture",1,"I hated that picture for three years"}},
{"s4_partner_say_died_032","any",2,"reg=law|tmp=veteran|day=2,20|mood=calm",{1,"Twenty-two years of death notifications, two officers, hat off, and you say the word died - never passed",2,"Who does ours?",1,"I figure it goes the other way now, everybody's notifying everybody"}},
{"s4_partner_stetson_033","any",2,"reg=law|day=1,12|mood=grim",{1,"Trooper at the checkpoint got bit through his pant leg - took off his hat and handed it to me",2,"Why the hat?",1,"Said it cost him ninety dollars in Lexington and he wasn't about to waste it"}},
{"s4_partner_long_shift_034","any",2,"reg=law|day=3,60|mood=sad",{1,"Deputy Moss's boy asks me every day when his daddy's getting off shift",2,"What do you tell him?",1,"Long shift, buddy, it's a long shift"}},
{"s4_partner_patch_sewing_035","any",2,"reg=law|day=5,90|mood=warm",{1,"I'm sewing Doyle's shoulder patch onto my sleeve, right under mine",2,"You can't sew",1,"I'm finding that out, thank you",2,"Give it here, hold the flashlight"}},
{"s4_partner_little_league_036","any",2,"reg=law|day=2,30|mood=angry",{1,"Why Pete? Pete never took a sick day - Pete went to every Little League game in this county",2,"It didn't have anything to do with who he was",1,"I know that, I'm mad about it anyway"}},
{"s4_partner_ronnie_door_037","any",3,"reg=law|day=2,30|mood=sad|world=door",{1,"I can still hear Ronnie through that door hollering my name - just my name, over and over",2,"I'm gonna go check on the back lot",3,"Lot's fine - sit down",3,"Go on, say it again if you need to - I'm listening"}},
{"s4_partner_doors_list_038","any",3,"reg=law,swat|tmp=veteran|day=8,120|mood=calm|world=door",{1,"I keep a list of every one of ours that got bit - day, hour, what they were doing",2,"What for?",1,"Because they all made the same mistake, and I want to know which one",3,"Doors, it's always a door"}},
{"s4_partner_k9_seven_039","any",2,"reg=law|day=4,60|mood=sad|world=vehicle",{1,"Riggs's dog still goes and sits by his cruiser at shift change - seven and seven, every day",2,"Somebody ought to take him in",1,"I did, he goes back out to the car at seven"}},
{"s4_partner_forty_cal_040","any",2,"reg=law|day=5,40|mood=grim",{1,"We split up Coleman's ammo, four boxes of forty",2,"Feels like robbing him",1,"He'd have split ours quicker, he'd have had it counted before we got the tarp over us"}},
{"s4_partner_mutter_recorder_041","any",1,"reg=law|day=6,90|mood=sad",{1,"Walt's pocket recorder still had a tape in it, him asking some teenager where he was Thursday night",1,"Played it four times, batteries are about done",1,"Saving what's left for a bad night"}},
{"s4_partner_four_joke_042","any",3,"reg=law|day=4,40|mood=funny",{1,"How many deputies does it take to hold a county?",2,"How many?",1,"More than four",3,"That's not a joke",1,"It was supposed to be one"}},
{"s4_partner_spit_harlan_043","any",2,"reg=law|day=1,6|mood=fear|world=vehicle",{1,"Man spit in Harlan's eye at the roadblock - just spit",2,"Spit ain't a bite",1,"Nobody knows what it ain't - Harlan's sitting in the transport van waiting to find out"}},
{"s4_partner_mills_hug_044","any",2,"reg=law|day=2,40|mood=warm",{1,"Sergeant Mills hugged me after the Riverside call - Mills, who shakes hands at funerals",2,"What'd he say?",1,"Not a word - Patted my vest twice and went back to his car"}},
{"s4_partner_silver_dollar_045","any",2,"reg=law|day=5,90|mood=sad",{1,"Holt carried a silver dollar from his first arrest, flipped it at every stop sign",2,"Where's it at now?",1,"My pocket, I flip it at stop signs, nobody stops at them anymore, but I do"}},
{"s4_partner_dottie_channel_046","any",2,"reg=law|day=2,30|mood=warm",{1,"When Dottie's voice came over the Rosewood channel I pulled onto the shoulder and just sat there",2,"She was at the firehouse the whole time?",1,"The whole time, I had the mic in both hands and couldn't make my thumb key it"}},
{"s4_partner_count_off_047","any",2,"reg=law,swat|tmp=veteran|day=3,90|mood=grim",{1,"Count off",2,"Two",1,"That's everybody?",2,"That's everybody",1,"Then two's the number - load up"}},
{"s4_partner_lights_on_048","any",2,"reg=law|day=3,60|mood=fear",{1,"Dreamed about Curtis, he was at roll call telling me I'd left my lights on",2,"Had you?",1,"I got up at three and went out to check"}},
{"s4_partner_bologna_049","any",2,"reg=law|day=4,60|mood=warm",{1,"Didn't eat for two days after Denny, nobody said one word about it",2,"We noticed",1,"I know you did, half a bologna sandwich on my clipboard every morning",2,"Don't look at me"}},
{"s4_partner_mutter_nameplate_050","any",1,"reg=law|day=3,90|mood=sad",{1,"Took his nameplate off the desk - BRANDT, black letters on brass",1,"Put it in my breast pocket, sits right over the vest plate"}},
{"s4_partner_swat_stack_051","any",3,"reg=swat|day=2,40|mood=sad",{1,"I still leave a gap in the stack where Kessler used to be - number two man",2,"I noticed, I've been bumping into nothing",3,"Close it up, he'd chew us out for a sloppy stack",1,"Tomorrow, I'll close it up tomorrow"}},
{"s4_partner_swat_shield_052","any",2,"reg=swat|day=2,60|mood=grim",{1,"Shield's got teeth marks along the viewport now, up top, right where Benny's face was",2,"Shield did its job",1,"Benny stepped out from behind it to pull a kid in - the shield did its job"}},
{"s4_partner_trooper_hat_brim_053","any",2,"reg=law|role=law_trooper|day=4,90|mood=sad|world=building",{1,"Keel used to crease his hat brim with a steam kettle every Sunday night",2,"Every Sunday, wouldn't let you touch it",1,"I tried it with a pot on the camp stove last night - ruined it, didn't have anybody to ask"}},
{"s4_partner_mutter_bit_quiet_054","any",1,"reg=law,swat|tmp=seasoned,veteran|day=3,90|hour=16,5|mood=fear",{1,"Clean hands, clean forearms, neck, you can't see your own neck",1,"Somebody's gonna have to look at my neck tomorrow, heh",1,"Tomorrow - not tonight"}},
{"s5_c01_insulin_cooler_001","any",3,"reg=military|day=1,10|hour=9,20|mood=sad",{1,"Man at the Muldraugh barrier had a foam cooler, insulin, he said - for his wife over in Vine Grove",2,"Vine Grove's outside, so he wanted out",1,"He didn't want out, he wanted somebody to carry the cooler across - just the cooler",3,"Anybody carry it?",1,"He's still standing out there holding it, whatever ice he had is water by now"}},
{"s5_c01_backseat_birth_002","any",3,"reg=military|day=2,20|hour=4,11|mood=warm|world=generator",{1,"Woman went into labor in a Buick right at the barrier this morning",2,"Doc go over?",1,"Couldn't - Doc talked the husband through it on the bullhorn from behind the jersey barriers - forty minutes",3,"Whole line went quiet, engineers even shut the generator off",1,"Little girl - Mama hollered the name across so it'd be written down someplace official",2,"Where'd you write it?",1,"Back of my range card, grace Ann, 0710"}},
{"s5_c01_split_farm_003","any",2,"reg=military|day=3,40|hour=4,9|mood=sad",{1,"Wire runs right between the Gaddie house and his dairy barn - house on our side, barn on theirs",2,"What happened to the cows?",1,"Nobody's milking 'em, he comes down to the wire at five every morning anyway and stands there while they bawl",2,"How long does he stand?",1,"About as long as it used to take him to milk"}},
{"s5_c01_honey_wagon_004","any",3,"reg=military|day=2,40|mood=funny|world=vehicle",{1,"Porta-john truck driver is the only civilian in Kentucky with a pass both directions",2,"Army'll let a whole county go, but Lord help us if the latrines back up",3,"Nobody's ever gonna fake being him, either, that's real security",1,"He waves at the MPs going through like he's the mayor"}},
{"s5_c01_video_tapes_005","any",2,"reg=military|day=1,8|mood=funny",{1,"Guy at the barrier asked could we get three rental tapes back to the video store in Radcliff - due Monday",2,"The late fee, that's what's keeping him up at night",1,"I told him the store would understand",2,"And what did he say to that?",1,"Said I'd never met the lady who runs it"}},
{"s5_c01_card_binder_006","any",2,"reg=military|day=2,20|mood=sad",{1,"Boy about eleven held a binder of baseball cards up at the wire - all of it, if his family could pass",2,"He have anything good?",1,"Said there's a rookie card worth sixty dollars, told me the page number, real serious about the page",2,"You tell him no?",1,"Told him keep 'em in the plastic sleeves, out of the damp - that's all I had to give him"}},
{"s5_c01_line_for_bridge_007","any",2,"reg=military|day=0,6|mood=calm|world=road",{1,"Lady rolled her window down and asked if this was the line for the bridge - like it was traffic",2,"Well, it is traffic, it's just not moving",1,"She asked how long the wait was, I said ma'am, I honestly don't know",2,"Truest thing anybody's said on this road all week"}},
{"s5_c01_handset_night_008","any",3,"reg=military|tmp=seasoned,veteran|day=3,60|hour=19,4|mood=grim",{1,"You were next to the lieutenant that night - what did he actually say on the net?",2,"Nothing, he had the handset up to his face and he didn't say a word",3,"Then who gave it?",2,"Sergeant Coyle took the handset off him - gentle, like taking the keys off a drunk",1,"And the lieutenant?",2,"Sat down on an ammo can, he's on another sector now - don't go asking him about it"}},
{"s5_c01_windbreaker_009","any",2,"reg=military|day=3,60|mood=sad",{1,"Kessler won't eat, says he saw his old shop teacher in the crowd at the gate that night",2,"Dark as it was? No way he could tell",1,"Says the man had on the booster club windbreaker, same one he wore to every home game",2,"Half the men in Muldraugh own that windbreaker",1,"That's what I told him, he said not with Mr. Priddy stitched on the pocket"}},
{"s5_c01_church_song_010","any",3,"reg=military|day=3,60|mood=grim",{1,"Before the gate went, they were singing, the whole crowd out there - some church song",2,"I don't want to hear about the singing",3,"My grandma's church sang that one every homecoming, I knew all the words",1,"Did you sing it?",3,"Moved my lips, rifle up, and moved my lips"}},
{"s5_c01_boy_over_wire_011","any",3,"reg=military|day=3,60|mood=sad|world=fence",{1,"Man came up the fence with a little boy on his back - got the boy to the top and let him down on our side",2,"And the man?",1,"Man didn't come over, he climbed back down on his side",3,"Where's the boy now?",1,"With the chaplain, drawing on MRE boxes, won't say his last name, says his daddy told him not to"}},
{"s5_c01_sitrep_word_012","any",2,"reg=military|tmp=seasoned,veteran|day=3,60|mood=angry",{1,"Read the sitrep that went up for that night, civil disturbance, dispersed",2,"Dispersed",1,"One word, typed nice and neat, no mistakes",2,"What word would you have used?",1,"I don't have one, that's why I'm so mad at theirs"}},
{"s5_c01_dozer_first_light_013","any",2,"reg=military|day=3,40|hour=5,10|mood=grim",{1,"Dozer's been going since first light over by the rail gate",2,"Don't walk over there",1,"Wasn't planning to",2,"You're looking - Looking's how you end up walking over there"}},
{"s5_c01_clean_weapon_014","any",2,"reg=military|day=3,60|mood=sad",{1,"I didn't fire, I need somebody to know that - my weapon's clean, they can check it",2,"I know you didn't, I was right next to you",1,"You watched me?",2,"The whole time, figured one of us ought to be able to say so"}},
{"s5_c01_cassette_ribbon_015","any",2,"reg=military|day=3,60|hour=19,5|mood=fear|world=wind",{1,"There's a cassette caught in the second strand, tape all pulled out, blowing around",2,"And you care why?",1,"So every time the wind picks up it catches the light tower - I keep thinking it's a flashlight coming",2,"Swap sectors with me, then",1,"No, I'll get used to it"}},
{"s5_c01_lawn_chair_016","any",3,"reg=military|day=4,30|hour=13,20|mood=sad",{1,"Miss Opal didn't come sit in her lawn chair today",2,"It's after three, she's always out there by two with that church fan",3,"She said yesterday her knee was acting up",1,"Yeah, her knee",2,"Chair's still sitting out there unfolded, somebody ought to fold it"}},
{"s5_c01_blue_chevy_017","any",2,"reg=military|day=1,15|mood=sad",{1,"That's my mama, lady in the blue Chevy, that's my actual mama out there",2,"Don't wave, lieutenant's looking right at us",1,"She's holding up a bag, she brought my good socks - I told her Thursday on the phone my feet hurt",2,"Nod, then, nod real big so she sees",1,"I'm nodding"}},
{"s5_c01_crop_duster_018","any",3,"reg=military|day=2,15|hour=6,19|mood=fear|world=vehicle",{1,"Crop duster came up off a grass strip past Ekron - flew right over the line, low, headed north",2,"Anybody fire?",1,"Not from here, net said it was being handled",3,"Handled how?",1,"Don't know, engine was still running when it went out of earshot - that's the part I'm keeping"}},
{"s5_c01_no_plates_019","any",2,"reg=military|tmp=seasoned,veteran|hour=0,5|mood=calm|world=cars",{1,"Two trucks outbound at 0300, no markings, no plates, no paperwork",2,"Captain let 'em through?",1,"Captain lifted the barrier himself, didn't write it in the log",2,"Then they didn't come through",1,"That's how I understood it"}},
{"s5_c01_not_sick_sign_020","any",3,"reg=military|day=1,15|mood=funny",{1,"Fella walked up with a cardboard sign says NOT SICK - thermometer sticking out of his mouth",2,"He get through?",3,"He took it out to show us, ninety-nine point one",1,"He shook it down real hard and stuck it back in to try again"}},
{"s5_c01_honor_student_021","any",2,"reg=military|day=0,10|mood=funny|world=vehicle",{1,"Minivan at the barrier had a bumper sticker, my child is an honor student at Rosewood Elementary",2,"Good for the child",1,"Kid sat in the back reading a library book the whole time his daddy yelled at me - never looked up once",2,"Now that's an honor student"}},
{"s5_c01_hand_signals_022","any",3,"reg=military|role=soldier_nco,soldier,soldier_green|day=1,30|mood=funny",{1,"Hand signals for the new people, finger spinning, turn around, flat palm, stop",2,"What's it mean when they give you this one back?",1,"Means they understood you fine and they'd like you to know how they feel about it",3,"I've got that one forty times today",1,"Then you're communicating clearly - good work"}},
{"s5_c01_hearse_023","any",3,"reg=military|day=1,12|mood=sad|world=road",{1,"Hearse from a funeral home in Brandenburg came up the road with papers for a burial outside the county",2,"Somebody in the back?",1,"Old lady, heart gave out the Thursday before any of this, family plot's twenty miles past the wire",3,"So what happened?",1,"Nothing crosses, driver backed it around real slow, like there was somebody back there to be careful of"}},
{"s5_c01_poultry_truck_024","any",2,"reg=military|day=3,14|hour=10,19|mood=grim|world=vehicle",{1,"Poultry truck's still on the shoulder by the bypass, driver walked off Sunday",2,"And the birds?",1,"Quit making any noise around Tuesday, wind's out of the south today, too",2,"I noticed around breakfast"}},
{"s5_c01_gas_station_map_025","any",3,"reg=military|day=1,30|mood=funny",{1,"Lieutenant's finding his way with a gas station road map, 'Welcome to Kentucky' on the front",2,"Where are the real maps?",3,"Locked in a conex back on post, nobody knows who has the key",1,"Gas station map's got every Baptist church marked, the Army never gave us that"}},
{"s5_c01_detour_arrow_026","any",2,"reg=military|day=2,40|mood=funny|world=road",{1,"Engineers put a detour sign up at the Rosewood junction - Arrow points straight back the way you came",2,"Detour, hell, that's a U-turn",1,"It's the only sign the highway department had left, and detour sounds friendlier"}},
{"s5_c01_swimmer_027","any",3,"reg=military|day=3,30|mood=grim",{1,"Searchlight picked up a swimmer off the boat ramp at Brandenburg last night - headed for Indiana",2,"Current's bad right there",3,"Did they make it?",1,"Light lost 'em about halfway",2,"Halfway's a long way to swim in the dark"}},
{"s5_c01_few_more_days_028","any",2,"reg=military|day=8,40|mood=sad",{1,"What do you tell 'em when they ask how long?",2,"Few more days",1,"It's been eleven",2,"Then it's been eleven few more days, they don't want the real number any more than I do"}},
{"s5_c01_grill_upwind_029","any",3,"reg=military|day=1,8|hour=16,21|mood=funny|world=wind",{1,"That family in the house past the barrier is grilling hamburgers - upwind - on purpose",2,"They're emptying the deep freeze before it spoils",3,"They're doing it forty feet upwind of a platoon eating crackers",1,"The dad just waved his spatula at me",2,"That's psychological warfare, somebody write him up"}},
{"s5_c01_tammy_traffic_030","any",1,"reg=military|tmp=fresh,seasoned|day=3,40|hour=21,4|mood=sad",{1,"When Tammy asks, I'll tell her I directed traffic, that's what it was - traffic",1,"Directed traffic in July - real hot - real boring, nothing to tell",1,"She'll buy it, she always said I was a lousy liar, so she'll never figure I'd try"}},
{"s5_c01_car_horn_031","any",2,"reg=military|hour=20,5|mood=fear|world=vehicle",{1,"Car horn's been going out past the curve for an hour - one long press",2,"Somebody slumped over the wheel",1,"Or somebody wants every one of them in three miles to come look",2,"It stopped",1,"Battery or somebody, doesn't matter which - wake up post three"}},
{"s5_c01_letterhead_032","any",3,"reg=military|day=1,15|mood=angry",{1,"Man at the barrier had a letter from his state representative - on letterhead, says let the bearer pass",2,"Real letterhead?",1,"Real letterhead, signed in blue ink and everything",3,"State representative doesn't outrank a jersey barrier",1,"That's about how the captain put it, with more words in it that start with F"}},
{"s5_c01_long_weekend_033","any",2,"reg=military|day=10,45|mood=funny",{1,"Active duty keeps calling us weekend warriors",2,"Well, it's Saturday",1,"It's been Saturday for two weeks, longest drill weekend in the history of the Kentucky Guard"}},
}
